// ---- lib/prompts.js (generated from source - do not edit here) ----
// ---------------------------------------------------------------------------
// Prompt loading and rendering.
// Prompts live in prompts/*.md as plain text with front matter, so they can be
// reviewed and diffed like code. n8n/build.mjs inlines them into the workflow
// JSON at build time; Node tooling reads them from disk.
//
// Placeholders:
//   {{name}}        required string - rendering throws if it is missing
//   {{name?}}       optional - renders as "(not available)" when missing
//   {{json:name}}   pretty-printed JSON block
//   {{list:name}}   array rendered as "- item" lines
// ---------------------------------------------------------------------------

const PLACEHOLDER = /\{\{\s*(json:|list:)?([a-zA-Z0-9_.]+)(\?)?\s*\}\}/g;

/** Split `---` front matter from the prompt body. */
function parseFrontMatter(text) {
  const raw = String(text);
  if (!raw.startsWith('---')) return { meta: {}, body: raw.trim() };
  const end = raw.indexOf('\n---', 3);
  if (end === -1) return { meta: {}, body: raw.trim() };

  const meta = {};
  for (const line of raw.slice(3, end).split('\n')) {
    const match = line.match(/^\s*([a-z_]+)\s*:\s*(.+?)\s*$/i);
    if (!match) continue;
    const [, key, value] = match;
    meta[key] = /^\d+(\.\d+)?$/.test(value) ? Number(value)
      : value === 'true' ? true
      : value === 'false' ? false
      : value.replace(/^["']|["']$/g, '');
  }
  return { meta, body: raw.slice(end + 4).trim() };
}

function lookup(vars, path) {
  return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), vars);
}

/** Fill a prompt template. Throws on a missing required variable. */
function renderTemplate(template, vars = {}) {
  const missing = [];
  const out = String(template).replace(PLACEHOLDER, (_match, kind, name, optional) => {
    const value = lookup(vars, name);
    const absent = value === undefined || value === null || value === '';

    if (absent) {
      if (!optional) { missing.push(name); return ''; }
      return kind === 'json:' ? '{}' : kind === 'list:' ? '- (none)' : '(not available)';
    }
    if (kind === 'json:') return JSON.stringify(value, null, 2);
    if (kind === 'list:') {
      const items = Array.isArray(value) ? value : [value];
      return items.length ? items.map((v) => `- ${typeof v === 'string' ? v : JSON.stringify(v)}`).join('\n') : '- (none)';
    }
    return Array.isArray(value) ? value.join(', ') : String(value);
  });

  if (missing.length) {
    throw new Error(`renderTemplate: missing required variables: ${[...new Set(missing)].join(', ')}`);
  }
  return out;
}

/** Variables a template expects, for validation and documentation. */
function templateVariables(template) {
  const required = new Set();
  const optional = new Set();
  for (const match of String(template).matchAll(PLACEHOLDER)) {
    (match[3] ? optional : required).add(match[2]);
  }
  return { required: [...required], optional: [...optional] };
}

/**
 * Render a prompt from a registry entry.
 * @param {object} prompt { meta, body } as produced by parseFrontMatter
 */
function renderPrompt(prompt, vars = {}) {
  const body = renderTemplate(prompt.body ?? prompt, vars);
  return {
    prompt: body,
    model: prompt.meta?.model ?? 'default',
    max_tokens: prompt.meta?.max_tokens ?? 2000,
    temperature: prompt.meta?.temperature ?? 0.2,
    schema_name: prompt.meta?.schema ?? null,
    version: prompt.meta?.version ?? '1'
  };
}

// ---- node logic ----
const PROMPT = {
  "meta": {
    "id": "reply_classification",
    "version": "1.0.0",
    "model": "default",
    "max_tokens": 900,
    "temperature": 0.1,
    "schema": "reply_classification"
  },
  "body": "ROLE\n\nYou perform reply classification for OptiFlow Solutions' Instagram outreach. A prospect has replied. Your classification decides what happens next: whether the follow-up sequence stays stopped, whether a human is pulled in, and what the response assistant is asked to draft.\n\nBe accurate rather than optimistic. Over-classifying replies as \"interested\" wastes the operator's day.\n\nINPUT\n\nBusiness: {{lead.business_name}} (@{{lead.instagram_handle}})\nNiche: {{niche.name}}\nTheir likely pain points:\n{{list:research.operational_pain_points}}\n\nConversation so far (oldest first):\n{{json:conversation.messages}}\n\nThe new inbound message to classify:\n\"{{message.body}}\"\n\nReceived: {{message.sent_at}}\n\nTASK\n\nClassify the message and extract what the next step needs.\n\nCLASSIFICATION RULES\n\nChoose exactly one `classification`:\n- interested: explicit positive intent to explore (\"yes, tell me more\", \"we'd be open to that\")\n- curious: engaged but non-committal (\"interesting\", \"how does that work?\")\n- question: a specific question that is not primarily about price\n- wants_details: asking for concrete information, a deck, examples, references\n- pricing: asking about cost, rates, or contract terms in any form\n- positive: friendly acknowledgement with no clear next step (\"thanks, appreciate it\")\n- maybe_later: interest deferred to a future time (\"not right now\", \"check back in Q1\")\n- not_interested: declines, with or without a reason\n- wrong_person: says they are not the right contact, or redirects you\n- objection: pushes back on premise, fit, trust or approach (\"we already have a team\", \"we don't outsource\")\n- unclear: cannot be classified with confidence from the text\n- auto_reply: an automated or away message\n- opt_out: asks not to be contacted again, in any wording\n\nAlso extract:\n- `intent`: one short phrase in their terms, describing what they actually want.\n- `sentiment`: positive | neutral | negative | mixed\n- `urgency`: high if they expect an answer soon or asked a direct question; medium if engaged without urgency; low otherwise.\n- `objection_type`: when classification is objection or not_interested, one of: has_internal_team, already_outsourced, no_budget, no_need, bad_timing, trust_concern, quality_concern, offshore_concern, not_decision_maker, other. Otherwise null.\n- `recommended_action`: continue_conversation | answer_question | send_pricing_context | route_to_human | mark_interested | mark_nurture | mark_not_interested | suppress_contact | redirect_to_named_contact | no_action\n- `stop_followups`: true for every classification except auto_reply. An automated away message is not a reply from a person.\n- `requires_human`: true for pricing, objection, opt_out, wrong_person, not_interested, and for anything where the next message could damage the relationship.\n- `suggested_stage`: REPLIED | CONVERSATION | INTERESTED | NURTURE | NOT_INTERESTED | CLOSED\n- `extracted`: any concrete facts worth storing - a named person to redirect to, a timeframe, a channel preference, a stated constraint.\n\nOUTPUT FORMAT\n\nReturn ONLY a JSON object.\n\nJSON SCHEMA\n\n{\n  \"classification\": \"one of the values above\",\n  \"intent\": \"short phrase\",\n  \"sentiment\": \"positive|neutral|negative|mixed\",\n  \"urgency\": \"high|medium|low\",\n  \"objection_type\": \"one of the values above, or null\",\n  \"recommended_action\": \"one of the values above\",\n  \"stop_followups\": true|false,\n  \"requires_human\": true|false,\n  \"suggested_stage\": \"one of the stage values above\",\n  \"confidence\": 0.0-1.0,\n  \"reasoning\": \"1-2 sentences pointing at the words that decided it\",\n  \"extracted\": { \"redirect_to\": null, \"timeframe\": null, \"constraints\": [], \"other\": null }\n}\n\nEDGE CASES\n\n- One-word replies (\"ok\", \"sure\", \"?\"): classify as unclear or curious; never as interested. Set confidence below 0.5.\n- An emoji-only reply: sentiment from the emoji, classification unclear, requires_human false, recommended_action continue_conversation.\n- Polite decline that also asks a question: classify by the QUESTION, note the decline in reasoning, and set requires_human true.\n- \"Send me your pricing\": classification pricing, requires_human true - a person decides what pricing to disclose.\n- \"Remove me\" / \"stop\" / \"don't message me\": opt_out, suppress_contact, requires_human true, suggested_stage NOT_INTERESTED. Never soften this or plan a rebuttal.\n- Hostile or abusive message: not_interested, objection_type other, suppress_contact, requires_human true. Do not draft a reply.\n- Message in another language: classify normally and record the language under extracted.other.\n- Multiple messages arrived at once: classify the combined intent and say so in reasoning."
};

const lead = $('Match To Lead').first().json;
const row = Array.isArray(lead) ? lead[0] : lead;
const inbound = $('Verify + Parse Inbound').first().json;
const logged = $input.first().json;
const message = Array.isArray(logged) ? logged[0] : logged;

const rendered = renderPrompt(PROMPT, {
  lead: { business_name: row?.business_name ?? 'unknown business', instagram_handle: row?.instagram_handle ?? 'unknown' },
  niche: { name: row?.niche_name ?? 'unknown' },
  research: { operational_pain_points: row?.potential_pain_points ?? [] },
  conversation: { messages: $('Conversation History').all().map((i) => i.json) },
  message: { body: inbound.body, sent_at: inbound.sent_at }
});

return [{ json: {
  lead_id: row?.lead_id ?? null,
  campaign_id: row?.campaign_id ?? null,
  conversation_id: message?.conversation_id ?? null,
  message_id: message?.id ?? null,
  message_body: inbound.body,
  prompt: rendered.prompt,
  model: $env.ANTHROPIC_MODEL || 'claude-sonnet-5',
  max_tokens: rendered.max_tokens,
  temperature: rendered.temperature,
  prompt_version: rendered.version
} }];

